<script setup lang="ts">
import { ref, watch } from 'vue';
import Button from 'primevue/button';
import InputText from 'primevue/inputtext';
import Message from 'primevue/message';
import Dialog from 'primevue/dialog';
import SessionAccess from '../components/SessionAccess.vue';
import { useAuth } from '../stores/auth';
import * as api from '../management-api';
const auth = useAuth(); const users = ref<api.User[]>([]); const families = ref<api.Family[]>([]); const members = ref<api.Member[]>([]);
const offset = ref(0); const familyOffset = ref(0); const memberOffset = ref(0); const familyId = ref(''); const memberId = ref('');
const username = ref(''); const password = ref(''); const role = ref<api.User['role']>('member'); const active = ref(true); const editing = ref<api.User | null>(null);
const busy = ref(false); const error = ref(''); const notice = ref(''); const confirm = ref(false);
async function run(action: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { await action(); } catch (e) { error.value = e instanceof Error ? e.message : 'Ошибка запроса'; } finally { busy.value = false; } }
async function load() { users.value = await api.listUsers(auth.token, offset.value); }
function reset() { editing.value = null; username.value = ''; password.value = ''; role.value = 'member'; active.value = true; memberId.value = ''; }
function edit(user: api.User) { editing.value = user; username.value = user.username; role.value = user.role; active.value = user.is_active; memberId.value = user.family_member_id || ''; password.value = ''; }
async function save() { await run(async () => { const link = memberId.value || null; if (editing.value) { await api.updateUser(auth.token, editing.value.id, { role: role.value, is_active: active.value, family_member_id: link, password: password.value || null }); } else { await api.createUser(auth.token, { username: username.value, password: password.value, role: role.value, family_member_id: link }); } const changedSelf = editing.value?.id === auth.user?.id; reset(); confirm.value = false; if (changedSelf) { await auth.signOut(); } else { await load(); notice.value = 'Пользователь сохранён. При изменении его прежние токены отозваны.'; } }); password.value = ''; }
function submit() { if (editing.value) confirm.value = true; else void save(); }
function page(delta: number) { void run(async () => { offset.value = Math.max(0, offset.value + delta * 20); await load(); }); }
function familyPage(delta: number) { void run(async () => { familyOffset.value = Math.max(0, familyOffset.value + delta * 20); families.value = await api.listFamilies(auth.token, familyOffset.value); }); }
function memberPage(delta: number) { void run(async () => { memberOffset.value = Math.max(0, memberOffset.value + delta * 20); members.value = await api.listMembers(auth.token, familyId.value, memberOffset.value); }); }
async function chooseFamily() { memberId.value = ''; memberOffset.value = 0; members.value = []; if (familyId.value) await run(async () => { members.value = await api.listMembers(auth.token, familyId.value); }); }
watch(() => auth.token, token => { users.value = []; families.value = []; members.value = []; error.value = ''; notice.value = ''; familyId.value = ''; offset.value = 0; familyOffset.value = 0; confirm.value = false; reset(); if (token && auth.isAdmin) void run(async () => { await load(); families.value = await api.listFamilies(token); }); }, { immediate: true });
</script>
<template>
<header><p class="eyebrow">УЧЁТНЫЕ ЗАПИСИ</p><h1>Пользователи и доступ</h1><p>Учётная запись связана с участником семьи. Системная роль определяет доступ к приложению.</p></header><SessionAccess />
<Message v-if="error" severity="error" role="alert">{{ error }}</Message><Message v-if="notice" severity="success" role="status">{{ notice }}</Message><p v-if="busy" role="status">Выполняется запрос…</p>
<p v-if="auth.user && !auth.isAdmin" class="empty">Управление пользователями доступно только администратору.</p>
<template v-if="auth.isAdmin"><section class="panel"><div class="section-title"><h2>Учётные записи</h2><Button label="Обновить" severity="secondary" :disabled="busy" @click="run(load)" /></div><p v-if="!users.length && !busy">Нет пользователей на этой странице.</p><ul class="record-list"><li v-for="user in users" :key="user.id" class="user-record"><div><strong>{{ user.username }}</strong><p>{{ user.role }} · {{ user.is_active ? 'Активен' : 'Отключён' }}</p></div><Button label="Изменить" severity="secondary" :disabled="busy" @click="edit(user)" /></li></ul><div class="pager"><Button label="Назад" :disabled="busy || !offset" @click="page(-1)" /><Button label="Далее" :disabled="busy || users.length < 20" @click="page(1)" /></div></section>
<section class="panel"><h2>{{ editing ? 'Изменить пользователя' : 'Создать пользователя' }}</h2><form @submit.prevent="submit"><label>Логин<InputText v-model="username" required minlength="3" maxlength="100" pattern="[a-zA-Z0-9][a-zA-Z0-9_.@-]+" :disabled="!!editing || busy" autocomplete="off" /></label><label>{{ editing ? 'Новый пароль (необязательно)' : 'Пароль' }}<InputText v-model="password" type="password" :required="!editing" minlength="12" maxlength="128" autocomplete="new-password" /></label><label>Системная роль<select v-model="role"><option value="admin">Администратор</option><option value="manager">Менеджер семьи</option><option value="member">Участник (просмотр)</option></select></label><label v-if="editing">Активность<input v-model="active" type="checkbox" aria-label="Пользователь активен" /></label>
<fieldset class="link-fields"><legend>Связь с участником семьи</legend><p>Сначала создайте семью и участника на странице «Семьи». Участник может иметь только одну учётную запись.</p><label>Семья<select v-model="familyId" :disabled="busy" @change="chooseFamily"><option value="">Выберите семью</option><option v-for="family in families" :key="family.id" :value="family.id">{{ family.name }}</option></select></label><div class="pager"><Button label="Предыдущие семьи" :disabled="busy || !familyOffset" @click="familyPage(-1)" /><Button label="Следующие семьи" :disabled="busy || families.length < 20" @click="familyPage(1)" /></div><label>Участник<select v-model="memberId" :required="role !== 'admin'" :disabled="busy"><option value="">Без связи (только администратор)</option><option v-if="memberId && !members.some(m => m.id === memberId)" :value="memberId">Текущий участник: {{ memberId }}</option><option v-for="member in members" :key="member.id" :value="member.id">{{ member.first_name }} {{ member.last_name }} — {{ member.role }}</option></select></label><div v-if="familyId" class="pager"><Button label="Предыдущие участники" :disabled="busy || !memberOffset" @click="memberPage(-1)" /><Button label="Следующие участники" :disabled="busy || members.length < 20" @click="memberPage(1)" /></div></fieldset>
<Button :label="editing ? 'Сохранить изменения' : 'Создать пользователя'" type="submit" :disabled="busy" /><Button v-if="editing" label="Отменить редактирование" severity="secondary" :disabled="busy" @click="reset" /></form></section></template>
<Dialog v-model:visible="confirm" modal header="Изменение доступа" :closable="!busy"><p>Сохранить изменения для {{ editing?.username }}? Все его токены будут отозваны.</p><Button label="Отмена" severity="secondary" :disabled="busy" @click="confirm = false" /><Button label="Подтвердить" :loading="busy" @click="save" /><Message v-if="error" severity="error" role="alert">{{ error }}</Message></Dialog>
</template>
